    if (query_result == NULL) {
        return -1;
    }

    /* Validate buffer size is sufficient to hold the result data */
    /* This check prevents buffer overflow (CWE-120) */
    if (result_len > buffer_size) {
        return -1;
    }

    /* Safely copy the query result data to the output buffer */
    /* Using memcpy since query_result and output_buffer should not overlap */
    /* The size has been validated above to prevent buffer overflow */
    memcpy(output_buffer, query_result, result_len);

    return 0;
}
